  chain = {
    bwl = "t|Blackwing Lair attunement;s|1|Blackhand's Command|starts from the item Blackhand's Command",
    ds2 = "t|The whole Dungeon Set 2 chain;s|Bracers|An Earnest Proposition|your Dungeon Set 1 bracers, 15 samples, 20 gold;s|Belt, Gloves|Just Compensation|7 quests via Mux Manascrambler (Gadgetzan). Delicate Arcanite Converter, 4 Greater Eternal Essence, 10 Stonescale Oil, 25 Volcanic Ash, 80 gold;s|Legs, Shoulders, Boots|Anthion's Parting Words|9 quests, from In Search of Anthion. 3 Dark Iron Bar, 3 Mooncloth, 20 Enchanted Leather, 4 Cured Rugged Hide, 8 Large Brilliant Shard, 4 Dark Rune;s|Helm, Chest|Saving the Best for Last|12 quests, from Bodley's Unfortunate Fate. Argent Dawn Honored to buy the Hallowed Brazier (120 gold), remains of three fire lords (one is the Duke of Cynders in Silithus, who must be summoned), 20 Bloodkelp, 40 Blackrock Bracer and a Flask of Supreme Power;p|Each step also takes your Dungeon Set 1 pieces for the same slots.",
    mc = "t|Molten Core attunement (optional);s|1|Attunement to the Core|Lothos Riftwaker, Blackrock Mountain",
    naxx = "t|Naxxramas attunement;s|1|The Dread Citadel - Naxxramas|Archmage Angela Dosantos, Eastern Plaguelands",
    onyxia_a = "t|Onyxia attunement (Alliance);s|1|Dragonkin Menace|Helendis Riverhorn, Burning Steppes;s|2|The True Masters|Helendis Riverhorn, Burning Steppes;s|3|The True Masters (2)|Magistrate Solomon, Redridge Mountains;s|4|The True Masters (3)|Highlord Bolvar Fordragon, Stormwind City;s|5|The True Masters (4)|Highlord Bolvar Fordragon, Stormwind City;s|6|The True Masters (5)|Magistrate Solomon, Redridge Mountains;s|7|The True Masters (6)|Marshal Maxwell, Burning Steppes;s|8|Marshal Windsor|Marshal Maxwell, Burning Steppes;s|9|Abandoned Hope|Marshal Windsor, Blackrock Depths;s|10|A Crumpled Up Note|starts from the item A Crumpled Up Note;s|11|A Shred of Hope|Marshal Windsor, Blackrock Depths;s|12|Jail Break!|Marshal Windsor, Blackrock Depths;s|13|Stormwind Rendezvous|Marshal Maxwell, Burning Steppes;s|14|The Great Masquerade|Reginald Windsor, Blackrock Depths;s|15|The Dragon's Eye|Highlord Bolvar Fordragon, Stormwind City;s|16|Drakefire Amulet|Haleh, Winterspring;fold|Show how to get the Seal of Ascension|ubrs_key",
    onyxia_h = "t|Onyxia attunement (Horde);s|1|Warlord's Command|starts from the item Warlord Goretooth's Command;s|2|Eitrigg's Wisdom|Warlord Goretooth, Badlands;s|3|For The Horde!|Thrall, Orgrimmar;s|4|What the Wind Carries|Thrall, Orgrimmar;s|5|The Champion of the Horde|Thrall, Orgrimmar;s|6|Mistress of Deception|Rexxar, Desolace;s|7|Oculus Illusions|Myranda the Hag, Western Plaguelands;s|8|Emberstrife|Myranda the Hag, Western Plaguelands;s|9|The Test of Skulls, Scryer|Emberstrife, Dustwallow Marsh;s|10|The Test of Skulls, Somnus|Emberstrife, Dustwallow Marsh;s|11|The Test of Skulls, Chronalis|Emberstrife, Dustwallow Marsh;s|12|The Test of Skulls, Axtroz|Emberstrife, Dustwallow Marsh;s|13|Ascension...|Emberstrife, Dustwallow Marsh;s|14|Blood of the Black Dragon Champion|Rexxar, Desolace;fold|Show how to get the Seal of Ascension|ubrs_key",
    ubrs_key = "t|Seal of Ascension (Upper Blackrock Spire key);s|1|Unadorned Seal of Ascension|random drop from enemies in and around Blackrock Spire, or the Auction House;s|2|Talk to Vaelan|on a ledge in Lower Blackrock Spire;s|3|Three gems in Lower Blackrock Spire|Gemstone of Spirestone (Highlord Omokk), Gemstone of Smolderthorn (War Master Voone), Gemstone of Bloodaxe (Overlord Wyrmthalak);s|4|Emberstrife|Wyrmbog, Dustwallow Marsh: weaken him, then use the unforged seal and the orb on him;s|5|Seal of Ascension|back to Vaelan;p|One player with the seal opens the door for the whole group.",
  },
  note = {
    ["Arathi Basin reputation"] = "t|Arathi Basin reputation;b|Play Arathi Basin to gain reputation with The League of Arathor (Alliance) or The Defilers (Horde).;b|The supply officer at the Arathi Basin entrance sells the set. Reputation needed and price per piece: not known.",
    lw_dragonscale = "t|Dragonscale Leatherworking;b|Learn it with the quest Dragonscale Leatherworking: level 40 and Leatherworking 225 needed.;b|Bring 2 Tough Scorpid Breastplate, 2 Tough Scorpid Gloves and 10 Worn Dragonscale to Peter Galen in Azshara.|@A;b|Bring 2 Tough Scorpid Breastplate, 2 Tough Scorpid Gloves and 10 Worn Dragonscale to Thorkaf Dragoneye in the Badlands.|@H;b|You can have only one of Dragonscale, Elemental and Tribal Leatherworking.",
    lw_elemental = "t|Elemental Leatherworking;b|Learn it with the quest Elemental Leatherworking: level 40 and Leatherworking 225 needed.;b|Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth and 2 Breath of Wind to Sarah Tanner in the Searing Gorge.|@A;b|Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth and 2 Breath of Wind to Brumn Winterhoof in the Arathi Highlands.|@H;b|You can have only one of Dragonscale, Elemental and Tribal Leatherworking.",
    lw_tribal = "t|Tribal Leatherworking;b|Learn it with the quest Tribal Leatherworking: level 40 and Leatherworking 225 needed.;b|Bring a Wild Leather Vest and a Wild Leather Helmet to Caryssia Moonhunter in Feralas.|@A;b|Bring a Wild Leather Vest and a Wild Leather Helmet to Se'Jib in Stranglethorn Vale.|@H;b|You can have only one of Dragonscale, Elemental and Tribal Leatherworking.",
    ["Punctured Voodoo Doll (Zul'Gurub)"] = "t|Punctured Voodoo Doll;p|Made from the Punctured Voodoo Doll for your class, a Zul'Gurub drop.",
    ["PvP rank"] = "t|How PvP rank works;b|Rank is worked out once a week from your honor. A week with under 15 honorable kills doesn't count.;b|Each week your rank points drop by 20%, then the points for that week's honor are added. Keep playing to hold your rank.;b|Rare set: rank 7 lets you buy the gloves and boots, rank 8 the chest and legs, rank 10 the helm and shoulders.;b|Epic set: rank 12 lets you buy the gloves, legs and boots, rank 13 the helm, shoulders and chest.;b|If you lose the rank later you keep what you bought.",
    ["Removed in patch 1.11"] = "t|Removed set;p|This set was a PvP rank reward before patch 1.11. It was replaced by a new set and can't be bought any more.",
    ["Scourge Invasion"] = "t|Scourge Invasion;p|A reward of the Scourge Invasion world event, earned with Necrotic Runes from the Argent Dawn. Not known if the event runs in WoW Forever.",
  },
